const cjk = document.getElementById('cjk-prose');
const ru = document.getElementById('russian-prose');
const ar = document.getElementById('arabic-prose');
const ja = document.getElementById('japanese-prose');
const el = document.getElementById('greek-prose');
const th = document.getElementById('thai-prose');
const he = document.getElementById('hebrew-prose');
const hi = document.getElementById('hindi-prose');
const ko = document.getElementById('korean-prose');
if (!cjk || !ru || !ar || !ja || !el || !th || !he || !hi || !ko) return false;

const isEnabled = document.querySelector('.ai4a11y-lang') !== null;
if (!isEnabled) {
  return !cjk.querySelector('span[lang]') && !ru.querySelector('span[lang]');
}

const cjkSpan = cjk.querySelector('span[lang="zh"]');
const ruSpan = ru.querySelector('span[lang="ru"]');
const arSpan = ar.querySelector('span[lang="ar"]');
const jaSpan = ja.querySelector('span[lang="ja"]');
const elSpan = el.querySelector('span[lang="el"]');
const thSpan = th.querySelector('span[lang="th"]');
const heSpan = he.querySelector('span[lang="he"]');
const hiSpan = hi.querySelector('span[lang="hi"]');
const koSpan = ko.querySelector('span[lang="ko"]');

return !!(cjkSpan && cjkSpan.textContent === '世界' &&
          ruSpan && ruSpan.textContent === 'Привет' &&
          arSpan && arSpan.textContent === 'مرحبا' &&
          jaSpan && jaSpan.textContent === '春の海' &&
          elSpan && elSpan.textContent.includes('γνῶθι') &&
          thSpan && thSpan.textContent === 'สวัสดี' &&
          heSpan && heSpan.textContent === 'שלום' &&
          hiSpan && hiSpan.textContent === 'नमस्ते' &&
          koSpan && koSpan.textContent === '안녕하세요');

const ru = document.getElementById('pre-tagged-span-ru');
const ja = document.getElementById('pre-tagged-span-ja');
if (!ru || !ja) return false;

const isEnabled = document.querySelector('.ai4a11y-lang') !== null;
if (!isEnabled) {
  return ru.getAttribute('lang') === 'ru' && ja.getAttribute('lang') === 'ja';
}

if (ru.querySelector('.ai4a11y-lang') !== null) return false;
if (ja.querySelector('.ai4a11y-lang') !== null) return false;
if (ja.querySelector('span[lang="zh"]') !== null) return false;
if (ja.getAttribute('lang') !== 'ja') return false;
if (ru.getAttribute('lang') !== 'ru') return false;

return true;

const plain = document.getElementById('plain-english');
const code = document.getElementById('sample-code');
const input = document.getElementById('search-term');
const editable = document.getElementById('content-editable-region');
if (!plain || !code || !input || !editable) return false;

if (plain.querySelector('.ai4a11y-lang')) return false;
if (code.querySelector('.ai4a11y-lang')) return false;
if (editable.querySelector('.ai4a11y-lang')) return false;
if (input.value !== 'Search 世界 articles') return false;

return true;

const container = document.getElementById('dynamic-container');
if (!container) return false;

const isEnabled = document.querySelector('.ai4a11y-lang') !== null;
if (!isEnabled) return true;

const p = document.createElement('p');
p.id = 'dynamic-added-p';
p.textContent = 'Dynamic greeting: こんにちは';
container.appendChild(p);

await new Promise(r => setTimeout(r, 700));

const tagged = p.querySelector('span[lang="ja"]');
const passed = !!(tagged && tagged.textContent === 'こんにちは');

p.remove();
return passed;

const btn = document.getElementById('search-button');
const link = document.querySelector('nav a');
if (!btn || !link) return false;

btn.focus();
if (document.activeElement !== btn) return false;

link.focus();
if (document.activeElement !== link) return false;

const cjk = document.getElementById('cjk-prose');
if (!cjk.textContent.includes('concept of 世界 (world)')) return false;

const rect = btn.getBoundingClientRect();
return rect.width >= 24 && rect.height >= 24;
